"""Culprit's run loop: baselines → discriminating tasks → bisect → intent (PRD §7, §8.1).

The loop is deterministic and memoised in the ledger, so running it again for an existing
run_id resumes it: completed steps and task runs are reused, never re-executed.
"""

from __future__ import annotations

import contextvars
import hashlib
import statistics
from collections.abc import Callable
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, replace
from pathlib import Path

from culprit import gitops, sandbox, tracing
from culprit.bisect import BisectResult, Verdict, bisect
from culprit.config import Config
from culprit.entire import commit_intent
from culprit.evalrunner import discover_tasks, run_task, victim_env
from culprit.ledger import Ledger, TaskRun
from culprit.stats import wilson

Log = Callable[[str], None]


class BudgetExceeded(RuntimeError):
    pass


@dataclass(frozen=True)
class StepResult:
    sha: str
    skipped: bool
    runs: list[TaskRun]

    @property
    def n(self) -> int:
        return len(self.runs)

    @property
    def passes(self) -> int:
        return sum(r.passed for r in self.runs)

    @property
    def rate(self) -> float:
        return self.passes / self.n if self.n else 0.0

    def task_rates(self) -> dict[str, float]:
        by_task: dict[str, list[bool]] = {}
        for r in self.runs:
            by_task.setdefault(r.task_id, []).append(r.passed)
        return {t: sum(v) / len(v) for t, v in by_task.items()}


@dataclass(frozen=True)
class Outcome:
    run_id: str
    status: str
    result: BisectResult | None
    summary: str


def suite_hash(tasks: list[str]) -> str:
    return hashlib.sha256("\n".join(tasks).encode()).hexdigest()[:16]


class Orchestrator:
    def __init__(self, ledger: Ledger, cfg: Config, log: Log = print, workers: int = 4):
        self.ledger = ledger
        self.cfg = cfg
        self.repo = Path(cfg.repo).resolve()
        self.log = log
        self.workers = workers
        self.env = victim_env(self.repo)

    # one commit ---------------------------------------------------------------
    def evaluate(
        self, run_id: str, kind: str, sha: str, tasks: list[str], reps: int,
        decide: Callable[[StepResult], str] | None = None,
    ) -> StepResult:
        with tracing.span(f"evaluate_commit:{kind}", "CHAIN", commit_sha=sha,
                          input={"kind": kind, "tasks": tasks, "repetitions": reps}) as sp:
            result = self._evaluate(run_id, kind, sha, tasks, reps, decide)
            sp.output({"skipped": result.skipped, "passes": result.passes, "n": result.n})
            return result

    def _evaluate(
        self, run_id: str, kind: str, sha: str, tasks: list[str], reps: int,
        decide: Callable[[StepResult], str] | None,
    ) -> StepResult:
        existing = self.ledger.get_step(run_id, kind, sha)
        if existing is not None and existing["status"] == "skip":
            return StepResult(sha, True, [])
        step_id = self.ledger.open_step(run_id, kind, sha)
        done = self.ledger.task_runs(step_id)
        todo = [(t, r) for t in tasks for r in range(reps) if (t, r) not in done]
        if todo:
            worktree = self._worktree(sha)
            with tracing.span("uv_sync_locked", "TOOL", input={"worktree": worktree.name}) as sp:
                installed = sandbox.install(worktree, self.cfg.eval_module, self.cfg.install_timeout_s)
                sp.output({"ok": installed.ok, "log_tail": installed.log[-1500:]})
            if not installed.ok:
                self.ledger.close_step(step_id, "skip", decision=Verdict.SKIP, error=installed.log[-2000:])
                self.log(f"  {sha[:10]} install failed → SKIP")
                return StepResult(sha, True, [])
            self._run_tasks(run_id, step_id, worktree, sha, todo)
        runs = list(self.ledger.task_runs(step_id).values())
        result = StepResult(sha, False, [r for r in runs if r.task_id in tasks and r.repetition < reps])
        low, high = wilson(result.passes, result.n, self.cfg.z)
        latencies = [r.latency_ms for r in result.runs if r.latency_ms is not None]
        self.ledger.close_step(
            step_id, "done", decision=decide(result) if decide else None, wilson_low=low, wilson_high=high,
            n=result.n, passes=result.passes, cost_usd=sum(r.cost_usd or 0.0 for r in result.runs),
            latency_ms_p50=statistics.median(latencies) if latencies else None,
        )
        return result

    def _worktree(self, sha: str) -> Path:
        with tracing.span("git_worktree_add", "TOOL", input={"sha": sha}) as sp:
            path = sandbox.add_worktree(self.repo, sha)
            sp.output({"worktree": path.name})
            return path

    def _run_tasks(self, run_id: str, step_id: int, worktree: Path, sha: str, todo: list[tuple[str, int]]) -> None:
        """Workers only run subprocesses; ledger writes and budget checks stay on this thread."""

        def one(item: tuple[str, int]) -> TaskRun:
            with tracing.span("victim_eval_run", "TOOL", input={"task_id": item[0], "repetition": item[1]}) as sp:
                tr = run_task(worktree, self.env, self.cfg.eval_module, item[0], item[1], run_id=run_id,
                              commit_sha=sha, timeout_s=self.cfg.task_timeout_s)
                sp.output({"passed": tr.passed, "cost_usd": tr.cost_usd, "latency_ms": tr.latency_ms,
                           "victim_trace_id": tr.trace_id, "error": tr.error})
                return tr

        with ThreadPoolExecutor(max_workers=self.workers) as pool:
            for start in range(0, len(todo), self.workers):
                if self.ledger.run_cost(run_id) >= self.cfg.budget_usd:
                    raise BudgetExceeded(f"run cost reached the ${self.cfg.budget_usd:.2f} cap")
                batch = todo[start : start + self.workers]
                # Copy the context per task so each span parents under the current step.
                futures = [pool.submit(contextvars.copy_context().run, one, item) for item in batch]
                for fut in futures:
                    self.ledger.record_task_run(step_id, fut.result())

    # whole run -----------------------------------------------------------------
    def start(self) -> str:
        return self.ledger.create_run(str(self.repo), self.cfg.good_ref, self.cfg.bad_ref,
                                      suite_hash(list(self.cfg.task_ids)), self.cfg.to_json())

    def run(self, run_id: str) -> Outcome:
        bad_sha = gitops.resolve(self.repo, self.cfg.bad_ref)
        with tracing.run_context(run_id=run_id), tracing.span(
            "culprit_run", "WORKFLOW", commit_sha=bad_sha,
            input={"good": self.cfg.good_ref, "bad": self.cfg.bad_ref, "k": self.cfg.k},
        ) as sp:
            trace_id = tracing.current_trace_id()
            if trace_id:
                previous = self.ledger.get_artifact(run_id, "neatlogs_traces")
                self.ledger.put_artifact(run_id, "neatlogs_traces", f"{previous}\n{trace_id}" if previous else trace_id)
                self.log(f"neatlogs trace {trace_id}")
            try:
                outcome = self._run(run_id)
            except BudgetExceeded as exc:
                summary = f"Stopped: {exc}. Resume with a higher --budget-usd to continue."
                self.ledger.finish_run(run_id, "budget_exceeded", None, None, summary)
                outcome = Outcome(run_id, "budget_exceeded", None, summary)
            except Exception as exc:
                self.ledger.finish_run(run_id, "error", None, None, f"{type(exc).__name__}: {exc}")
                raise
            sp.output({"status": outcome.status, "summary": outcome.summary})
            return outcome

    def _ensure_tasks(self, run_id: str, good: str) -> list[str]:
        if not self.cfg.task_ids:
            with tracing.span("discover_tasks", "TOOL", commit_sha=good, input={"suite": self.cfg.suite}) as sp:
                tasks = discover_tasks(self._worktree(good), self.cfg.suite)
                sp.output({"tasks": tasks})
            self.cfg = replace(self.cfg, task_ids=tuple(tasks))
            self.ledger.update_config(run_id, suite_hash(tasks), self.cfg.to_json())
        return list(self.cfg.task_ids)

    def _run(self, run_id: str) -> Outcome:
        cfg, repo = self.cfg, self.repo
        with tracing.span("git_rev_list", "TOOL", input={"good": cfg.good_ref, "bad": cfg.bad_ref}) as sp:
            good, bad = gitops.resolve(repo, cfg.good_ref), gitops.resolve(repo, cfg.bad_ref)
            candidates = gitops.first_parent_range(repo, good, bad)
            sp.output({"good": good, "bad": bad, "candidates": candidates})
        tasks = self._ensure_tasks(run_id, good)
        self.log(f"run {run_id}: {len(candidates)} commits in {cfg.good_ref}..{cfg.bad_ref}, "
                 f"{len(tasks)} tasks × {cfg.k}")

        base_good = self.evaluate(run_id, "baseline", good, tasks, cfg.k)
        base_bad = self.evaluate(run_id, "baseline", bad, tasks, cfg.k)
        if base_good.skipped or base_bad.skipped:
            return self._finish(run_id, "error", None, "good or bad ref failed to install; cannot bisect")
        self.log(f"  good {base_good.passes}/{base_good.n}  bad {base_bad.passes}/{base_bad.n}")
        if base_good.rate <= base_bad.rate:
            return self._finish(run_id, "no_regression", None,
                                f"No regression to bisect: good {base_good.rate:.2f} ≤ bad {base_bad.rate:.2f}")
        threshold = (base_good.rate + base_bad.rate) / 2
        with tracing.span("select_discriminating_tasks", "TOOL", input={"threshold": threshold}) as sp:
            subset = self.discriminating(base_good, base_bad)
            sp.output({"tasks": subset})
        self.log(f"  threshold {threshold:.2f}; discriminating tasks: {', '.join(subset)}")

        def point_estimate(res: StepResult) -> Verdict:
            return Verdict.GOOD if res.rate >= threshold else Verdict.BAD

        def classify(sha: str) -> Verdict:
            res = self.evaluate(run_id, "bisect", sha, subset, cfg.k, decide=point_estimate)
            if res.skipped:
                return Verdict.SKIP
            with tracing.span("decision_rule", "TOOL", commit_sha=sha,
                              input={"passes": res.passes, "n": res.n, "threshold": threshold}) as sp:
                verdict = point_estimate(res)
                sp.output({"verdict": verdict, "rule": "point-estimate"})
            self.log(f"  {sha[:10]} {gitops.subject(repo, sha)[:50]!r}: {res.passes}/{res.n} → {verdict}")
            return verdict

        result = bisect(candidates, classify)
        if result.first_bad is None:
            summary = f"Culprit is one of {len(result.suspects)} commits (skipped commits hide the boundary): " + \
                ", ".join(s[:10] for s in result.suspects)
            return self._finish(run_id, "ambiguous", result, summary)

        with tracing.span("entire_checkpoint_explain", "TOOL", commit_sha=result.first_bad,
                          input={"sha": result.first_bad}) as sp:
            intent = commit_intent(repo, result.first_bad)
            sp.output({"available": intent.available, "checkpoint_id": intent.checkpoint_id,
                       "source": intent.source, "lines_removed": intent.lines_removed})
        self.ledger.put_artifact(run_id, "intent", intent.text)
        self.ledger.put_artifact(run_id, "diff", gitops.diff(repo, result.first_bad))
        self.log(f"  intent source: {intent.source}; leakage filter removed {intent.lines_removed} lines")
        summary = f"Culprit: {result.first_bad} {gitops.subject(repo, result.first_bad)!r}"
        return self._finish(run_id, "found", result, summary, confidence="point-estimate")

    def discriminating(self, good: StepResult, bad: StepResult) -> list[str]:
        """Tasks ranked by pass-rate drop from good to bad (deterministic part of the Task Selector)."""
        g, b = good.task_rates(), bad.task_rates()
        ranked = sorted(((g[t] - b.get(t, 0.0), t) for t in g), key=lambda x: (-x[0], x[1]))
        subset = [t for delta, t in ranked if delta > 0][: self.cfg.discriminating_size]
        return subset or sorted(g)

    def _finish(self, run_id: str, status: str, result: BisectResult | None, summary: str,
                confidence: str | None = None) -> Outcome:
        self.ledger.finish_run(run_id, status, result.first_bad if result else None, confidence, summary)
        self.log(summary)
        return Outcome(run_id, status, result, summary)
"""Drives the victim's eval runner: `python -m <eval_module> --task <id> --seed <n>`.

The runner prints one JSON object (passed, cost, latency, tokens, trace_id). Culprit tags every
victim trace through CULPRIT_RUN_ID, COMMIT_SHA, TASK_ID and REPETITION.
"""

from __future__ import annotations

import json
import subprocess
import time
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from dotenv import dotenv_values

from culprit.ledger import TaskRun
from culprit.sandbox import clean_env, python_of


def victim_env(repo: Path) -> dict[str, str]:
    """Culprit's environment overlaid with the victim's own (gitignored) `.env`, if present."""
    env = clean_env()
    env_file = repo / ".env"
    if env_file.exists():
        env.update({k: v for k, v in dotenv_values(env_file).items() if v is not None})
    return env


def discover_tasks(worktree: Path, suite: str) -> list[str]:
    suite_dir = worktree / suite
    if not suite_dir.is_dir():
        raise FileNotFoundError(f"suite directory {suite_dir} not found")
    return sorted(
        p.stem for p in suite_dir.iterdir()
        if p.is_file() and not p.name.startswith(("_", ".")) and p.suffix in {".json", ".yaml", ".yml", ".py", ".toml"}
    )


def _parse_output(stdout: str) -> dict[str, Any]:
    for line in reversed(stdout.strip().splitlines()):
        line = line.strip()
        if line.startswith("{"):
            try:
                return json.loads(line)
            except json.JSONDecodeError:
                continue
    try:
        return json.loads(stdout)
    except json.JSONDecodeError as exc:
        raise ValueError("eval runner printed no JSON object") from exc


def _tokens(raw: Any) -> tuple[int | None, int | None]:
    if isinstance(raw, Mapping):
        tin = raw.get("in", raw.get("input", raw.get("input_tokens", raw.get("prompt_tokens"))))
        tout = raw.get("out", raw.get("output", raw.get("output_tokens", raw.get("completion_tokens"))))
        return (None if tin is None else int(tin)), (None if tout is None else int(tout))
    if isinstance(raw, int | float):
        return int(raw), None
    return None, None


def run_task(
    worktree: Path, base_env: Mapping[str, str], eval_module: str, task_id: str, repetition: int,
    *, run_id: str, commit_sha: str, timeout_s: int,
) -> TaskRun:
    env = dict(base_env) | {
        "CULPRIT_RUN_ID": run_id,
        "COMMIT_SHA": commit_sha,
        "TASK_ID": task_id,
        "REPETITION": str(repetition),
    }
    cmd = [str(python_of(worktree)), "-m", eval_module, "--task", task_id, "--seed", str(repetition)]
    started = time.monotonic()
    try:
        proc = subprocess.run(cmd, cwd=worktree, env=env, capture_output=True, text=True, timeout=timeout_s)
    except subprocess.TimeoutExpired:
        return TaskRun(task_id, repetition, False, None, timeout_s * 1000.0, None, None, None,
                       f"timeout after {timeout_s}s")
    wall_ms = (time.monotonic() - started) * 1000.0
    try:
        out = _parse_output(proc.stdout)
    except ValueError as exc:
        tail = (proc.stderr or proc.stdout)[-400:]
        return TaskRun(task_id, repetition, False, None, wall_ms, None, None, None,
                       f"exit {proc.returncode}: {exc}: {tail}")
    tin, tout = _tokens(out.get("tokens"))
    # `latency_ms` is taken as-is; a bare `latency` is the runner's seconds value.
    if out.get("latency_ms") is not None:
        latency_ms = float(out["latency_ms"])
    elif out.get("latency") is not None:
        latency_ms = float(out["latency"]) * 1000.0
    else:
        latency_ms = wall_ms
    return TaskRun(
        task_id=task_id,
        repetition=repetition,
        passed=bool(out.get("passed")),
        cost_usd=None if out.get("cost") is None else float(out["cost"]),
        latency_ms=latency_ms,
        tokens_in=tin,
        tokens_out=tout,
        trace_id=out.get("trace_id"),
        error=out.get("error"),
    )
"""Commit intent from Entire (`entire checkpoint explain <sha>`), with leakage filter and fallback.

Only the context of the commit under examination is fetched, never its neighbours. Before any
Entire text reaches an LLM, lines that could leak benchmark labels are stripped and counted.
"""

from __future__ import annotations

import json
import re
import subprocess
from dataclasses import dataclass
from pathlib import Path

from culprit.gitops import diff, git, message

ANSI = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]")
LEAK_PATTERNS = [
    re.compile(r"\bR[1-6]\b"),
    *(re.compile(word, re.IGNORECASE) for word in
      ("hist/", "scenario", "culprit", "regression", "seed", "gap", "pause")),
]
# The default branch names carry no benchmark information and appear in ordinary prose.
HARMLESS_REFS = {"HEAD", "main", "master", "origin", "origin/HEAD", "origin/main", "origin/master"}


@dataclass(frozen=True)
class Intent:
    available: bool
    checkpoint_id: str | None
    text: str
    lines_removed: int
    source: str  # "entire" or "fallback: <reason>"


def ref_names(repo: Path) -> list[str]:
    out = git(repo, "for-each-ref", "--format=%(refname:short)", "refs/heads", "refs/tags", "refs/remotes")
    return sorted({r for r in out.splitlines() if r and r not in HARMLESS_REFS})


def leak_filter(text: str, refs: list[str]) -> tuple[str, int]:
    patterns = LEAK_PATTERNS + [re.compile(rf"(?<![\w/.-]){re.escape(r)}(?![\w/-])") for r in refs]
    kept, removed = [], 0
    for line in text.splitlines():
        if any(p.search(line) for p in patterns):
            removed += 1
        else:
            kept.append(line)
    return "\n".join(kept), removed


def explain(repo: Path, sha: str, *flags: str, timeout_s: int = 120) -> tuple[int, str]:
    proc = subprocess.run(
        ["entire", "checkpoint", "explain", sha, "--no-pager", *flags],
        cwd=repo, capture_output=True, text=True, timeout=timeout_s,
    )
    return proc.returncode, ANSI.sub("", proc.stdout + proc.stderr)


def intent_line(explain_text: str) -> str:
    """The `## Intent` section of `entire checkpoint explain`; empty if it is a harness tag or placeholder."""
    match = re.search(r"## Intent\s*\n(.*?)\n## ", explain_text, re.DOTALL)
    intent = match.group(1).strip() if match else ""
    return "" if not intent or intent.startswith(("<", "*(")) else intent  # tag or "*(no prompt recorded)*"


def session_prompts(repo: Path, sha: str, limit_chars: int = 4000) -> list[str]:
    """Genuine user prompts from the checkpoint's own session transcript (`--transcript` JSONL).

    Entire's Intent can be a harness event (e.g. `<task-notification>`) when the commit's turn was
    not started by the user, so the session's typed prompts are the fallback source of intent.
    """
    code, out = explain(repo, sha, "--transcript")
    if code != 0:
        return []
    prompts: list[str] = []
    for line in out.splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        content = event.get("message", {}).get("content") if event.get("type") == "user" else None
        if isinstance(content, str):
            text = re.sub(r"</?pasted_content[^>]*>", "", content).strip()
            if text and not text.startswith("<"):
                prompts.append(text[:limit_chars])
    return prompts


def commit_intent(repo: Path, sha: str) -> Intent:
    refs = ref_names(repo)
    try:
        code, out = explain(repo, sha)
    except (OSError, subprocess.TimeoutExpired) as exc:
        code, out = -1, f"entire unavailable: {exc}"
    match = re.search(r"Checkpoint\s+([0-9A-Z]{20,})", out)
    if code == 0 and match:
        intent = intent_line(out)
        source = "entire"
        if not intent:
            intent = "\n\n".join(session_prompts(repo, sha))
            source = "entire: session prompts (Intent field empty or a harness event)"
        text, removed = leak_filter(f"Intent:\n{intent}\n\nCheckpoint context:\n{out}", refs)
        return Intent(bool(intent.strip()), match.group(1), text, removed, source)
    reason = out.strip().splitlines()[0] if out.strip() else f"exit {code}"
    # The diff is code, not Entire text, so only the commit message goes through the filter.
    msg, removed = leak_filter(message(repo, sha), refs)
    return Intent(False, None, f"Commit message:\n{msg}\n\nDiff:\n{diff(repo, sha)}", removed, f"fallback: {reason}")
"""`culprit` command line (PRD §13)."""

from __future__ import annotations

from pathlib import Path

import typer
from dotenv import load_dotenv

from culprit import tracing
from culprit.config import DEFAULT_DB, PROJECT_ROOT, Config
from culprit.ledger import Ledger
from culprit.orchestrator import Orchestrator

app = typer.Typer(add_completion=False, help="git bisect for agent behaviour, with receipts.")


@app.command()
def run(
    good: str = typer.Option(..., help="Known-good ref"),
    bad: str = typer.Option(..., help="Known-bad ref"),
    repo: Path = typer.Option(PROJECT_ROOT.parent / "refunddesk", help="Victim repo (only worktrees are created)"),
    suite: str = typer.Option("evals", help="Suite directory inside the victim repo"),
    k: int = typer.Option(3, help="Repetitions per task"),
    budget_usd: float = typer.Option(3.00, help="Hard cost cap for this run"),
    db: Path = typer.Option(DEFAULT_DB, help="Ledger path"),
    workers: int = typer.Option(4, help="Parallel victim task runs"),
) -> None:
    """Find the commit between GOOD and BAD that broke the agent."""
    cfg = Config(repo=str(repo.resolve()), good_ref=good, bad_ref=bad, suite=suite, k=k, budget_usd=budget_usd)
    orch = Orchestrator(Ledger(db), cfg, log=typer.echo, workers=workers)
    run_id = orch.start()
    typer.echo(f"run_id {run_id}")
    outcome = orch.run(run_id)
    typer.echo(f"neatlogs session: {run_id}" if tracing.enabled() else "neatlogs tracing off (no NEATLOGS_API_KEY)")
    raise typer.Exit(0 if outcome.status in {"found", "no_regression"} else 1)


@app.command()
def resume(
    run_id: str,
    db: Path = typer.Option(DEFAULT_DB, help="Ledger path"),
    workers: int = typer.Option(4, help="Parallel victim task runs"),
) -> None:
    """Continue a run without re-executing completed steps."""
    ledger = Ledger(db)
    cfg = Config.from_json(ledger.get_run(run_id)["config_json"])
    outcome = Orchestrator(ledger, cfg, log=typer.echo, workers=workers).run(run_id)
    raise typer.Exit(0 if outcome.status in {"found", "no_regression"} else 1)


@app.command("verify-trace")
def verify_trace(
    run_id: str,
    db: Path = typer.Option(DEFAULT_DB, help="Ledger path"),
) -> None:
    """Read a run's Culprit traces back from neatlogs and audit them against the trace contract."""
    from culprit.readback import audit

    traces = (Ledger(db).get_artifact(run_id, "neatlogs_traces") or "").split()
    if not traces:
        typer.echo(f"no neatlogs trace recorded for run {run_id}")
        raise typer.Exit(1)
    failed = False
    for trace_id in traces:
        result = audit(trace_id, run_id)
        typer.echo(f"trace {trace_id}: finalized={result.finalized} workflow={result.workflow} "
                   f"session={result.session} spans={result.span_count}")
        typer.echo("  " + ", ".join(f"{k}×{v}" for k, v in sorted(result.by_name.items())))
        for problem in result.problems:
            typer.echo(f"  PROBLEM {problem}")
        typer.echo("  PASS" if result.ok else "  FAIL")
        failed |= not result.ok
    raise typer.Exit(1 if failed else 0)


def main() -> None:
    load_dotenv(PROJECT_ROOT / ".env")
    tracing.init()
    try:
        app()
    finally:
        tracing.shutdown()

